-- Catalogue validé le 6 octobre 2026 : 81 méditations avec un script écrit chacune,
-- 13 respirations à rythme propre. Chaque séance a une catégorie (moment de vie)
-- et un objectif. Les séances retirées restent en base, inactives, pour garder
-- l'historique de progression qui les référence.

alter table public.sessions add column if not exists goal text
  check (goal is null or goal in ('sleep', 'relax', 'calm', 'focus', 'energy', 'emotion', 'perspective', 'kindness'));

on conflict (id) do update set
  title = excluded.title,
  intention = excluded.intention,
  duration_seconds = excluded.duration_seconds,
  category_id = excluded.category_id,
  goal = excluded.goal,
  pillar = excluded.pillar,
  practice_type = excluded.practice_type,
  artwork_path = excluded.artwork_path,
  is_premium = excluded.is_premium,
  is_active = true,
  keywords = excluded.keywords,
  catalog_version = public.sessions.catalog_version + 1,
  updated_at = now();

-- Les narrations ElevenLabs sont publiées dans session-audio/fr/<id>.m4a :
-- les anciens fichiers MP3 ne sont plus servis.
update public.sessions set audio_path = null, updated_at = now()
where id in ('decouverte_1', 'discover_counting', 'decouverte_3', 'decouverte_2', 'discover_body_scan', 'discover_rain', 'discover_open_sitting', 'express_1', 'express_8', 'express_5', 'between_calls', 'new_focus_reset', 'meditation_06', 'creative_block', 'decision_pause', 'afternoon_fog', 'meditation_09', 'after_work', 'work_impostor', 'work_after_criticism', 'express_6', 'new_after_conflict', 'rel_before_hard_talk', 'emotion_5', 'rel_deep_listening', 'rel_worry_for_someone', 'rel_letting_go_grudge', 'rel_gratitude_someone', 'lonely_evening', 'meditation_05', 'emotion_3', 'emotion_4', 'emo_sadness', 'emo_anger', 'meditation_10', 'new_thoughts_on_clouds', 'afternoon_reframe', 'meditation_08', 'emo_uncertainty', 'emotion_1', 'emo_inner_critic', 'new_safe_place', 'small_joy', 'express_2', 'commute_home', 'doorstep_pause', 'new_walking_pause', 'new_sensory_shelter', 'blue_hour', 'friday_release', 'sunday_reset', 'daybreak_stillness', 'morning_wake_body', 'express_3', 'new_soft_reset', 'morning_kind_start', 'express_7', 'actualite_1', 'actualite_2', 'actualite_3', 'actualite_5', 'meditation_16', 'screen_off', 'express_4', 'new_body_scan_sleep', 'sleep_2', 'sleep_4', 'sleep_3', 'sleep_cognitive_shuffle', 'sleep_5', 'sleep_1', 'middle_of_night', 'night_watch', 'night_sky', 'stress_3', 'new_nidra_pause', 'stress_5', 'gentle_recovery', 'meditation_15', 'body_tension', 'body_mindful_stretch', 'breathing_1', 'breath_sigh', 'new_long_exhale', 'new_box_breathing', 'breath_triangle', 'stress_2', 'breath_sleep_descent', 'breathing_3', 'breathing_2', 'breathing_5', 'breathing_4', 'breath_cooling', 'breath_counting');

