where id in ('actualite_4', 'stress_1', 'stress_4', 'emotion_2', 'new_morning_window', 'new_commute_boundary', 'daybreak_grounding', 'morning_breathing_space', 'late_morning_focus', 'lunch_reset', 'after_lunch_energy', 'before_meeting', 'evening_unwind', 'evening_release', 'after_dinner', 'monday_arrival', 'meditation_01', 'meditation_02', 'meditation_03', 'meditation_04', 'meditation_07', 'meditation_11', 'meditation_12', 'meditation_13', 'meditation_14', 'meditation_17');
